import{_ as i,o as a,c as t,ag as r}from"./chunks/framework.D1K3FKSn.js";const u=JSON.parse('{"title":"Design decisions","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/architecture/design-decisions.html"}],["meta",{"property":"og:title","content":"Design decisions | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/architecture/design-decisions.html"}],["meta",{"name":"twitter:title","content":"Design decisions | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"architecture/design-decisions.md","filePath":"architecture/design-decisions.md"}'),s={name:"architecture/design-decisions.md"};function n(o,e,l,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="design-decisions" tabindex="-1">Design decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design decisions&quot;">​</a></h1><h2 id="_1-screen-space-error-lod-selection" tabindex="-1">1. Screen-space error LOD selection <a class="header-anchor" href="#_1-screen-space-error-lod-selection" aria-label="Permalink to &quot;1. Screen-space error LOD selection&quot;">​</a></h2><p>SSE determines when to use finer/coarser LODs based on how many pixels a voxel projects to. This adapts automatically to screen resolution, FOV, and viewing distance. A single threshold (default 8.0 pixels) controls the quality/performance tradeoff.</p><h2 id="_2-lru-eviction" tabindex="-1">2. LRU eviction <a class="header-anchor" href="#_2-lru-eviction" aria-label="Permalink to &quot;2. LRU eviction&quot;">​</a></h2><p>Frame-based touch tracking identifies which bricks were recently used. Bricks not touched for the longest time are evicted first when the atlas is full. This naturally prioritizes the current working set.</p><h2 id="_3-differential-updates" tabindex="-1">3. Differential updates <a class="header-anchor" href="#_3-differential-updates" aria-label="Permalink to &quot;3. Differential updates&quot;">​</a></h2><p>Only load bricks that are missing; touch existing ones to keep them fresh. This minimizes network requests and GPU uploads when the camera moves incrementally.</p><h2 id="_4-empty-brick-skipping" tabindex="-1">4. Empty brick skipping <a class="header-anchor" href="#_4-empty-brick-skipping" aria-label="Permalink to &quot;4. Empty brick skipping&quot;">​</a></h2><p>Pre-computed statistics (min/max/avg) in Kiln&#39;s sharded binary index file allow skipping bricks with no useful data before any network request. This is particularly effective for sparse volumes like CT scans with large air regions.</p><h2 id="_5-multi-slot-indirection" tabindex="-1">5. Multi-slot indirection <a class="header-anchor" href="#_5-multi-slot-indirection" aria-label="Permalink to &quot;5. Multi-slot indirection&quot;">​</a></h2><p>Coarse LOD bricks fill multiple cells in the indirection table (2^lod per dimension), with LOD priority to prevent coarse from overwriting fine. This enables seamless LOD transitions handled entirely by the indirection lookup.</p><h2 id="_6-lod-255-empty-marker" tabindex="-1">6. LOD 255 = empty marker <a class="header-anchor" href="#_6-lod-255-empty-marker" aria-label="Permalink to &quot;6. LOD 255 = empty marker&quot;">​</a></h2><p>A special indirection value indicates &quot;known empty, don&#39;t render&quot; so coarse data doesn&#39;t bleed through holes in finer LODs.</p><h2 id="_7-663-physical-bricks" tabindex="-1">7. 66³ physical bricks <a class="header-anchor" href="#_7-663-physical-bricks" aria-label="Permalink to &quot;7. 66³ physical bricks&quot;">​</a></h2><p>The 1-voxel overlap on all sides enables seamless trilinear filtering at brick boundaries without special-case shader logic.</p><h2 id="_8-pinned-base-lod" tabindex="-1">8. Pinned base LOD <a class="header-anchor" href="#_8-pinned-base-lod" aria-label="Permalink to &quot;8. Pinned base LOD&quot;">​</a></h2><p>The coarsest LOD is loaded at startup and never evicted, ensuring there&#39;s always a complete (if low-resolution) representation available while finer data streams in.</p><h2 id="_9-compute-shader-raymarching" tabindex="-1">9. Compute shader raymarching <a class="header-anchor" href="#_9-compute-shader-raymarching" aria-label="Permalink to &quot;9. Compute shader raymarching&quot;">​</a></h2><p>Kiln uses compute shaders rather than fragment shaders for raymarching. The core loop is one thread per pixel — functionally identical to a fullscreen-triangle fragment shader — so the raymarching itself doesn&#39;t rely on compute-specific features like shared memory or subgroup operations. The practical benefits are pipeline simplicity (compute-to-compute chaining for temporal accumulation, direct <code>textureStore</code> output, resolution scaling without intermediate framebuffers) and future headroom for GPU-native optimizations (shared memory, subgroups, indirect dispatch). See <a href="/reference/webgpu.html">WebGPU Notes</a> for details.</p>',19)])])}const m=i(s,[["render",n]]);export{u as __pageData,m as default};
